n=19
orig=[[0]*n for _ in range(n)]
markers=[(2,6),(3,5),(3,7),(3,13),(4,6),(4,12),(4,14),(5,13),(9,8),(10,7),(10,9),(11,8),(11,14),(12,13),(12,15),(13,3),(13,14),(14,2),(14,4),(15,3)]
for r,c in markers: orig[r][c]=3
centers=[(3,6,8),(4,13,4),(10,8,0),(12,14,1),(14,3,2)]
for r,c,v in centers: orig[r][c]=v
out=[row[:] for row in orig]
# Horizontal rays from numbered centers; own adjacent arms are transparent, other gray arms stop the ray.
for r,c,v in centers:
    if v==0: continue
    out[r][c]=v
    for dc in (-1,1):
        cc=c+dc
        while 0<=cc<n:
            if orig[r][cc]==3:
                if abs(cc-c)==1: pass
                else: break
            else: out[r][cc]=v
            cc+=dc
# Empty object's horizontal axis; zero is transparent except as a crossing.
for r,c,v in centers:
    if v==0:
        for j in range(n):
            if orig[r][j]!=3: out[r][j]=0
# Vertical rays from numbered centers, overriding horizontal crossings.
for r,c,v in centers:
    if v==0: continue
    out[r][c]=v
    for dr in (-1,1):
        rr=r+dr
        while 0<=rr<n:
            if orig[rr][c]==3:
                if abs(rr-r)==1: pass
                else: break
            else: out[rr][c]=v
            rr+=dr
# Empty object's vertical axis, which leaves a gap through horizontal strokes.
for r,c,v in centers:
    if v==0:
        for i in range(n):
            if orig[i][c]!=3: out[i][c]=0
import json
print(json.dumps(out))
